/*
 * A129693  Right truncatable primes in base 9 (written in decimal form).
 * https://oeis.org/A129693
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini, full
 * Formula:   a(n) = the nth right‑truncatable prime in base 9 (written in
 *            decimal). The sequence is generated by a breadth‑first search:
 *            start from the single‑digit base‑9 primes {2,3,5,7} and
 *            repeatedly append a base‑9 digit 0–8 (creating new numbers x*9 +
 *            d). A new number is kept only if it is prime. This r...
 * Range:     u8 none, u16 n <= 50, u32 n <= 52, u64 n <= 68, u128 n <= 68,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>
#include "../utils/is_prime_big.h"

seq_t a(idx_t n) {
    /* Static cache of all right‑truncatable primes in base 9. */
    static seq_t *primes = NULL;  /* dynamic array of primes */
    static size_t plen = 0;       /* number of primes stored */
    static size_t pcap = 0;       /* allocated capacity */

    /* Initialise cache lazily on first call. */
    if (primes == NULL) {
        /* Initial capacity: enough for the known 68 primes. */
        pcap = 128;
        primes = (seq_t *)malloc(pcap * sizeof(seq_t));
        if (!primes) return 0;  /* allocation failure – return 0 */

        /* Push initial single‑digit base‑9 primes. */
        const seq_t init[] = {2,3,5,7};
        plen = 0;
        for (size_t i = 0; i < 4; ++i) {
            primes[plen++] = init[i];
        }

        /* BFS queue pointer: index of next parent to expand. */
        size_t qidx = 0;
        while (qidx < plen) {
            seq_t parent = primes[qidx++];
            seq_t base = parent * 9;           /* prefix multiplier */
            for (int d = 0; d <= 8; ++d) {      /* append digit d */
                seq_t cand = base + d;          /* new candidate */
                if (is_prime_big(cand)) {
                    /* Grow array if needed. */
                    if (plen == pcap) {
                        size_t newcap = pcap * 2;
                        seq_t *tmp = (seq_t *)realloc(primes, newcap * sizeof(seq_t));
                        if (!tmp) { /* allocation failed */
                            free(primes);
                            primes = NULL;
                            return 0;
                        }
                        primes = tmp;
                        pcap = newcap;
                    }
                    primes[plen++] = cand;
                }
            }
        }
        /* Reallocate to exact size to free surplus memory. */
        if (plen < pcap) {
            seq_t *tmp = (seq_t *)realloc(primes, plen * sizeof(seq_t));
            if (tmp) primes = tmp;
            pcap = plen;
        }
    }

    /* Return the requested element if it exists. */
    if (n >= 1 && (idx_t)n <= plen) {
        return primes[(idx_t)n - 1];
    }
    return 0;  /* out of bounds – sequence ends after 68 elements */
}
